CREATE MATERIALIZED VIEW mart_executive.region_health AS SELECT r.region_id,r.region_name,r.region_dir,COUNT(p.policy_id) policy_count,SUM(p.premium_amount) written_premium,AVG(p.premium_amount) avg_premium,AVG(p.payment_gap_months) avg_payment_gap,COUNT(DISTINCT l.lead_id) lead_count,COUNT(DISTINCT l.lead_id) FILTER(WHERE l.lead_status='Converted') converted_leads,COUNT(DISTINCT p.current_agent_id) active_agents FROM core.region r LEFT JOIN core.policy p USING(region_id) LEFT JOIN core.customer c ON c.region_id=r.region_id LEFT JOIN core.lead l ON l.customer_id=c.customer_id GROUP BY 1,2,3 WITH NO DATA;
CREATE UNIQUE INDEX IF NOT EXISTS ux_executive_region_health ON mart_executive.region_health(region_id);
